K, W, C = 'Knowledge', 'Wisdom', 'Command'
S, R = 'stated', 'reflection'
def ins(t, b, text): return {'type': t, 'basis': b, 'text': text}
def keeps(t): return {'dir': 'keeps', 'text': t}
def loses(t): return {'dir': 'loses', 'text': t}
def between(t): return {'dir': 'between', 'text': t}
AGREE = between("Hebrew, Greek, Latin and King James agree in substance; only the rendering of the divine name and small turns of phrase differ.")
NUM = [between("Verse numbering: the site follows the Hebrew and Greek, where English 29:1 is 28:69.")]
STORE = [loses("Hebrew 'your basket and your kneading bowl' is lost."), keeps("Greek 'your storehouses and your reserves'."), between("The Latin and King James follow the Hebrew.")]
YOUNG = [loses("Hebrew 'the increase of your cattle and the young of your flock' is lost."), keeps("Greek 'the herds of your cattle and the flocks of your sheep'."), between("The Latin and King James follow the Hebrew.")]
GOD = [keeps("Greek adds 'your God'.")]
DISEASE = [between("The disease and crop terms are ancient and uncertain in every column; the prose does not convert them to modern diagnoses.")]

def v(received, explain, shared, k, w, lost, entries=None, cmd=None):
    inst = [ins(K, S, k)]
    if cmd: inst.append(ins(C, S, cmd))
    inst.append(ins(W, R, w))
    return {'received': received, 'explain': explain, 'shared': shared, 'instructions': inst, 'entries': entries if entries is not None else [], 'lost': lost}

